function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must have the same length.';
  if (operations[0] !== 'FindElements' || operations.slice(1).includes('FindElements')) return 'Start with "FindElements" exactly once.';
  if (operations.length < 2 || operations.length - 1 > 10000) return 'Make 1 to 10^4 calls to find.';
  const tree = args[0] && args[0][0];
  if (!Array.isArray(tree) || tree.length < 1 || tree[0] === null) return 'The tree needs a root.';
  if (tree.some(v => v !== null && v !== -1)) return 'Every node holds -1: the tree arrives overwritten.';
  // Walk the level-order list to count nodes and find the deepest one.
  const depths = [0];
  let head = 0;
  let height = 0;
  for (let i = 1; i < tree.length; i += 2) {
    if (head >= depths.length) return 'The level-order list continues after the tree has ended.';
    const depth = depths[head++];
    for (const value of [tree[i], tree[i + 1]]) {
      if (value === -1) {
        depths.push(depth + 1);
        height = Math.max(height, depth + 1);
      }
    }
  }
  if (depths.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (height > 20) return 'The tree is at most 20 edges deep.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'find') return `Unknown operation ${operations[i]}.`;
    const target = Array.isArray(args[i]) ? args[i][0] : undefined;
    if (args[i].length !== 1 || !Number.isInteger(target) || target < 0 || target > 1000000) return 'find takes one whole number from 0 to 10^6.';
  }
  return null;
}

