class FindElements {
  constructor(root) {
    this.values = new Set();
    this.recover(root, 0);
  }

  recover(node, value) {
    if (!node) {
      return;
    }
    node.val = value;
    this.values.add(value);
    this.recover(node.left, 2 * value + 1);
    this.recover(node.right, 2 * value + 2);
  }

  find(target) {
    return this.values.has(target);
  }
}

