class FindElements {
  constructor(root) {
    this.root = root;
  }

  find(target) {
    // Relabel on the fly with a breadth-first walk every time, without storing anything.
    const queue = [[this.root, 0]];
    for (let i = 0; i < queue.length; i++) {
      const [node, label] = queue[i];
      if (label === target) return true;
      if (node.left) queue.push([node.left, label * 2 + 1]);
      if (node.right) queue.push([node.right, label * 2 + 2]);
    }
    return false;
  }
}

