function generate(rand, size) {
  const large = size === 'large';
  const pick = k => Math.floor(rand() * k);
  const n = large ? 900 : 1 + pick(10);
  const chain = !large && rand() < 0.2;
  // Grow a random shape no deeper than 20 edges, tracking each node's true label.
  const root = { label: 0, depth: 0, left: null, right: null };
  const labels = [0];
  const open = [root];
  while (labels.length < n && open.length) {
    const k = chain ? open.length - 1 : pick(open.length);
    const parent = open[k];
    const side = parent.left ? 'right' : parent.right ? 'left' : (rand() < 0.5 ? 'left' : 'right');
    const child = { label: 2 * parent.label + (side === 'left' ? 1 : 2), depth: parent.depth + 1, left: null, right: null };
    parent[side] = child;
    labels.push(child.label);
    if (parent.left && parent.right) {
      open[k] = open[open.length - 1];
      open.pop();
    }
    if (child.depth < 20) open.push(child);
  }
  const tree = [];
  const queue = [root];
  for (let i = 0; i < queue.length; i++) {
    if (queue[i] === null) {
      tree.push(null);
      continue;
    }
    tree.push(-1);
    queue.push(queue[i].left, queue[i].right);
  }
  while (tree[tree.length - 1] === null) tree.pop();
  const findable = labels.filter(label => label <= 1000000);
  const top = Math.min(1000000, 2 * Math.max(...findable) + 3);
  const calls = large ? 499 : 1 + pick(8);
  const operations = ['FindElements'];
  const args = [[tree]];
  for (let c = 0; c < calls; c++) {
    const roll = rand();
    const target = roll < 0.45 ? findable[pick(findable.length)] : roll < 0.9 ? pick(top + 1) : pick(1000001);
    operations.push('find');
    args.push([target]);
  }
  return [operations, args];
}
